CREATE TABLE public.units (code text PRIMARY KEY CHECK(code IN ('NP1','NP2','NP3','NP4')), legal_name text NOT NULL DEFAULT '', cnpj text NOT NULL DEFAULT '', state_registration text NOT NULL DEFAULT '', address text NOT NULL DEFAULT '', postal_code text NOT NULL DEFAULT '');
GRANT SELECT ON public.units TO anon, authenticated; GRANT INSERT,UPDATE,DELETE ON public.units TO authenticated; GRANT ALL ON public.units TO service_role;
ALTER TABLE public.units ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Units for registration" ON public.units FOR SELECT TO anon,authenticated USING(true);
CREATE POLICY "Admin manages units" ON public.units FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
