CREATE TABLE public.job_functions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text UNIQUE NOT NULL CHECK(length(name) BETWEEN 1 AND 100));
GRANT SELECT ON public.job_functions TO anon,authenticated; GRANT INSERT,UPDATE,DELETE ON public.job_functions TO authenticated; GRANT ALL ON public.job_functions TO service_role;
ALTER TABLE public.job_functions ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Functions for registration" ON public.job_functions FOR SELECT TO anon,authenticated USING(true);
CREATE POLICY "Admin manages functions" ON public.job_functions FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
INSERT INTO public.job_functions(name) VALUES ('Diretoria'),('Gerente Geral / Gestor Geral'),('Supervisor'),('Vendedor'),('Operador'),('Outros');
CREATE TABLE public.sectors (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), unit_code text NOT NULL REFERENCES public.units(code), name text NOT NULL CHECK(length(name) BETWEEN 1 AND 100), UNIQUE(unit_code,name));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.sectors TO authenticated; GRANT ALL ON public.sectors TO service_role;
ALTER TABLE public.sectors ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.profiles ADD COLUMN unit_code text REFERENCES public.units(code), ADD COLUMN sector_id uuid REFERENCES public.sectors(id), ADD COLUMN requested_job_role text, ADD COLUMN requested_unit_code text REFERENCES public.units(code);
ALTER TABLE public.courses ADD COLUMN target_job_role text, ADD COLUMN unit_code text REFERENCES public.units(code);
CREATE OR REPLACE FUNCTION public.has_role(_user_id uuid,_role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles r JOIN auth.users u ON u.id=r.user_id JOIN public.profiles p ON p.id=u.id WHERE r.user_id=_user_id AND r.role=_role AND u.email_confirmed_at IS NOT NULL AND (CASE WHEN _role='admin' THEN lower(u.email) IN ('rh@natalpneus.com.br','lucas.felipemoura.santos@gmail.com') ELSE p.status='approved' END)) $$;
CREATE OR REPLACE FUNCTION public.is_approved() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.has_role(auth.uid(),'admin') OR EXISTS(SELECT 1 FROM public.profiles p JOIN auth.users u ON u.id=p.id WHERE p.id=auth.uid() AND p.status='approved' AND u.email_confirmed_at IS NOT NULL) $$;
CREATE OR REPLACE FUNCTION public.can_read_all() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'director') OR public.has_role(auth.uid(),'general_manager') $$;
REVOKE ALL ON FUNCTION public.has_role(uuid,public.app_role),public.is_approved(),public.can_read_all() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.has_role(uuid,public.app_role),public.is_approved(),public.can_read_all() TO authenticated;
CREATE POLICY "Readers see sectors" ON public.sectors FOR SELECT TO authenticated USING(public.can_read_all() OR (public.is_approved() AND unit_code=(SELECT p.unit_code FROM public.profiles p WHERE p.id=auth.uid())));
CREATE POLICY "Admin manages sectors" ON public.sectors FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE POLICY "Leadership reads profiles" ON public.profiles FOR SELECT TO authenticated USING(public.can_read_all());
CREATE POLICY "Supervisor reads approved unit" ON public.profiles FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'supervisor') AND unit_code=(SELECT p.unit_code FROM public.profiles p WHERE p.id=auth.uid()));
CREATE OR REPLACE FUNCTION public.handle_new_user() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
INSERT INTO public.profiles(id,email,full_name,phone,requested_job_role,requested_unit_code,status) VALUES(new.id,new.email,left(coalesce(new.raw_user_meta_data->>'full_name',''),200),nullif(new.raw_user_meta_data->>'phone',''),CASE WHEN EXISTS(SELECT 1 FROM public.job_functions WHERE name=new.raw_user_meta_data->>'job_role') THEN new.raw_user_meta_data->>'job_role' END,CASE WHEN EXISTS(SELECT 1 FROM public.units WHERE code=new.raw_user_meta_data->>'unit_code') THEN new.raw_user_meta_data->>'unit_code' END,'pending');
INSERT INTO public.user_roles(user_id,role) VALUES(new.id,'employee');
IF new.email_confirmed_at IS NOT NULL AND lower(new.email) IN ('rh@natalpneus.com.br','lucas.felipemoura.santos@gmail.com') THEN INSERT INTO public.user_roles(user_id,role) VALUES(new.id,'admin') ON CONFLICT DO NOTHING; UPDATE public.profiles SET status='approved' WHERE id=new.id; END IF; RETURN new; END $$;
CREATE OR REPLACE FUNCTION public.sync_verified_admin() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
IF new.email_confirmed_at IS NOT NULL AND lower(new.email) IN ('rh@natalpneus.com.br','lucas.felipemoura.santos@gmail.com') THEN INSERT INTO public.user_roles(user_id,role) VALUES(new.id,'admin') ON CONFLICT DO NOTHING; UPDATE public.profiles SET status='approved' WHERE id=new.id;
ELSE DELETE FROM public.user_roles WHERE user_id=new.id AND role='admin'; END IF; RETURN new; END $$;
CREATE TRIGGER sync_verified_admin AFTER UPDATE OF email,email_confirmed_at ON auth.users FOR EACH ROW EXECUTE FUNCTION public.sync_verified_admin();
INSERT INTO public.user_roles(user_id,role) SELECT id,'admin'::public.app_role FROM auth.users WHERE email_confirmed_at IS NOT NULL AND lower(email) IN ('rh@natalpneus.com.br','lucas.felipemoura.santos@gmail.com') ON CONFLICT DO NOTHING;
CREATE TABLE public.admin_audit (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor_id uuid, action text NOT NULL, table_name text NOT NULL, record_id text, before_data jsonb, after_data jsonb, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.admin_audit TO authenticated; GRANT ALL ON public.admin_audit TO service_role;
ALTER TABLE public.admin_audit ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Admin reads audit" ON public.admin_audit FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE OR REPLACE FUNCTION public.audit_admin_change() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE oldj jsonb; newj jsonb; BEGIN IF TG_OP<>'INSERT' THEN oldj:=to_jsonb(old); END IF; IF TG_OP<>'DELETE' THEN newj:=to_jsonb(new); END IF; INSERT INTO public.admin_audit(actor_id,action,table_name,record_id,before_data,after_data) VALUES(auth.uid(),TG_OP,TG_TABLE_NAME,coalesce(newj->>'id',oldj->>'id',newj->>'code',oldj->>'code'),oldj,newj); IF TG_OP='DELETE' THEN RETURN old; ELSE RETURN new; END IF; END $$;
CREATE TRIGGER profiles_audit AFTER UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.audit_admin_change();
CREATE TRIGGER roles_audit AFTER INSERT OR UPDATE OR DELETE ON public.user_roles FOR EACH ROW EXECUTE FUNCTION public.audit_admin_change();
CREATE TRIGGER units_audit AFTER UPDATE ON public.units FOR EACH ROW EXECUTE FUNCTION public.audit_admin_change();
CREATE TRIGGER functions_audit AFTER INSERT OR UPDATE OR DELETE ON public.job_functions FOR EACH ROW EXECUTE FUNCTION public.audit_admin_change();
CREATE TRIGGER sectors_audit AFTER INSERT OR UPDATE OR DELETE ON public.sectors FOR EACH ROW EXECUTE FUNCTION public.audit_admin_change();
CREATE OR REPLACE FUNCTION public.review_employee(_id uuid,_status public.access_status,_unit text,_job text,_sector uuid,_role public.app_role,_producer boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Forbidden'; END IF;
IF EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_id AND role='admin') THEN RAISE EXCEPTION 'Admin account cannot be reviewed'; END IF;
IF _role NOT IN ('employee','director','general_manager','supervisor') THEN RAISE EXCEPTION 'Invalid access profile'; END IF;
IF _status='approved' AND (NOT EXISTS(SELECT 1 FROM public.units WHERE code=_unit) OR NOT EXISTS(SELECT 1 FROM public.job_functions WHERE name=_job) OR NOT EXISTS(SELECT 1 FROM auth.users WHERE id=_id AND email_confirmed_at IS NOT NULL)) THEN RAISE EXCEPTION 'Confirm email, unit and function before approval'; END IF;
IF _sector IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.sectors WHERE id=_sector AND unit_code=_unit) THEN RAISE EXCEPTION 'Sector does not belong to store'; END IF;
UPDATE public.profiles SET status=_status,unit_code=_unit,unit=_unit,job_role=_job,sector_id=_sector WHERE id=_id;
DELETE FROM public.user_roles WHERE user_id=_id AND role<>'admin'; INSERT INTO public.user_roles(user_id,role) VALUES(_id,_role); IF _producer THEN INSERT INTO public.user_roles(user_id,role) VALUES(_id,'producer') ON CONFLICT DO NOTHING; END IF; END $$;
REVOKE ALL ON FUNCTION public.review_employee(uuid,public.access_status,text,text,uuid,public.app_role,boolean) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.review_employee(uuid,public.access_status,text,text,uuid,public.app_role,boolean) TO authenticated;
CREATE TABLE public.sales_results (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), unit_code text NOT NULL REFERENCES public.units(code), competence date NOT NULL CHECK(extract(day FROM competence)=1), dimension text NOT NULL CHECK(dimension IN ('store','sector','employee')), sector_id uuid REFERENCES public.sectors(id), employee_id uuid REFERENCES public.profiles(id), amount_cents bigint NOT NULL CHECK(amount_cents BETWEEN 0 AND 9000000000000), created_by uuid DEFAULT auth.uid(), updated_by uuid DEFAULT auth.uid(), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK((dimension='store' AND sector_id IS NULL AND employee_id IS NULL) OR (dimension='sector' AND sector_id IS NOT NULL AND employee_id IS NULL) OR (dimension='employee' AND employee_id IS NOT NULL)));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.sales_results TO authenticated; GRANT ALL ON public.sales_results TO service_role;
ALTER TABLE public.sales_results ENABLE ROW LEVEL SECURITY;
CREATE UNIQUE INDEX sales_month_scope ON public.sales_results(unit_code,competence,dimension,coalesce(sector_id,'00000000-0000-0000-0000-000000000000'::uuid),coalesce(employee_id,'00000000-0000-0000-0000-000000000000'::uuid));
CREATE POLICY "Revenue read scope" ON public.sales_results FOR SELECT TO authenticated USING(public.can_read_all() OR (public.has_role(auth.uid(),'producer') AND dimension='employee' AND employee_id=auth.uid()));
CREATE POLICY "Admin manages revenue" ON public.sales_results FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE OR REPLACE FUNCTION public.validate_sale() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF new.sector_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.sectors WHERE id=new.sector_id AND unit_code=new.unit_code) THEN RAISE EXCEPTION 'Invalid store sector'; END IF; IF new.employee_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=new.employee_id AND unit_code=new.unit_code) THEN RAISE EXCEPTION 'Invalid store employee'; END IF; IF TG_OP='INSERT' THEN new.created_by:=auth.uid(); ELSE new.created_by:=old.created_by; new.created_at:=old.created_at; END IF; new.updated_by:=auth.uid(); new.updated_at:=now(); RETURN new; END $$;
CREATE TRIGGER sales_validate BEFORE INSERT OR UPDATE ON public.sales_results FOR EACH ROW EXECUTE FUNCTION public.validate_sale();
CREATE TRIGGER sales_audit AFTER INSERT OR UPDATE OR DELETE ON public.sales_results FOR EACH ROW EXECUTE FUNCTION public.audit_admin_change();
DROP POLICY "Approved users read courses" ON public.courses;
CREATE POLICY "Scoped course reading" ON public.courses FOR SELECT TO authenticated USING(public.can_read_all() OR (public.is_approved() AND (target_job_role IS NULL OR target_job_role=(SELECT job_role FROM public.profiles WHERE id=auth.uid())) AND (unit_code IS NULL OR unit_code=(SELECT p.unit_code FROM public.profiles p WHERE id=auth.uid()))));
DROP POLICY "Signed in read badges" ON public.badges;
CREATE POLICY "Approved reads badges" ON public.badges FOR SELECT TO authenticated USING(public.is_approved());
DROP POLICY "Own or admin read awarded badges" ON public.employee_badges;
CREATE POLICY "Scoped badge histories" ON public.employee_badges FOR SELECT TO authenticated USING(public.can_read_all() OR (public.is_approved() AND user_id=auth.uid()));
DROP POLICY "Signed in read course and badge files" ON storage.objects;
CREATE POLICY "Scoped file reads" ON storage.objects FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin') OR (public.is_approved() AND ((bucket_id='badges') OR (bucket_id='course-files' AND EXISTS(SELECT 1 FROM public.courses c WHERE c.file_path=name)))));
CREATE TRIGGER courses_audit AFTER INSERT OR UPDATE OR DELETE ON public.courses FOR EACH ROW EXECUTE FUNCTION public.audit_admin_change();
CREATE TRIGGER badges_audit AFTER INSERT OR UPDATE OR DELETE ON public.badges FOR EACH ROW EXECUTE FUNCTION public.audit_admin_change();
CREATE TRIGGER employee_badges_audit AFTER INSERT OR UPDATE OR DELETE ON public.employee_badges FOR EACH ROW EXECUTE FUNCTION public.audit_admin_change();